package android.os;public class Binder implements IBinder {public static int getCallingUid(){return Process.myUid();}public boolean transact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{return onTransact(code,data,reply,flags);}protected boolean onTransact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{return false;}public String getInterfaceDescriptor(){return "";}public void linkToDeath(DeathRecipient r,int f){}public boolean unlinkToDeath(DeathRecipient r,int f){return true;}}